WITH ValidPayments AS (SELECT * FROM payments WHERE (order_id IS NULL AND method IN ('cash', 'promptpay')) OR status != 'REFUNDED'), PaymentsStats AS (SELECT order_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(method))) AS method_values, COUNT(DISTINCT amount) AS unique_methods FROM ValidPayments GROUP BY order_id) SELECT * FROM PaymentsStats WHERE unique_methods < 4 ORDER BY 1 DESC LIMIT 10
